INSERT INTO `edu_task` (`id`, `task_code`, `task_title`, `course_name`, `teacher_id`, `target_class`, `task_requirement`, `required_nodes_json`, `rubric_json`, `deadline`, `task_status`) VALUES
(1, 'TASK-2026-001', '实训一：构建支持知识增强(RAG)的智能代码评审工作流', 'Web应用综合实训', 2, '计科1班', '要求4人小组协同搭建一个不少于4个节点的AI工作流，必须包含输入节点、知识检索节点、大模型节点与输出节点，并附上完整测试运行记录与不少于100字的实训总结报告。', '{"minNodes": 4, "mustInclude": ["INPUT", "KNOWLEDGE", "LLM", "OUTPUT"]}', '[{"item": "拓扑完整性与节点规范", "maxScore": 30}, {"item": "Prompt工程与知识库结合度", "maxScore": 40}, {"item": "沙箱运行效果与实验报告", "maxScore": 30}]', DATEADD('DAY', 14, NOW()), 1);

